function itemType(it){const id=it[0];if(['toybox','bookshelfplay','arttable'].includes(id))return 'Play Furniture';if(['playmat','doll','dollhousemini','blocks','rocker','trainset','puzzle','crafts','puppet','dollstroller','tents','marbles'].includes(id))return 'Toys';if(['bathcabinet','towelrack','hamper','shelf'].includes(id))return 'Bathroom Storage';if(['bath','toilet','bathsink','bathmirror','rubberduck','bathmat','shower','soap','towels','toothbrush','bathplant'].includes(id))return 'Bath Fixtures';if(['tablepink','tablewood','tableglass','tableheart','table','coffeetable'].includes(id))return 'Tables';if(id.startsWith('chair')||id==='chair')return 'Chairs';if(id==='fridge')return 'Fridges';if(['stove','sink','cupboard','mixer','dininglamp'].includes(id))return 'Appliances';if(['tea','cupcake'].includes(id))return 'Fridge Food';if(['cake','birthdaycake'].includes(id))return 'Treats';if(['bed','bedcanopy','bedcloud','bedpink'].includes(id))return 'Beds';if(['desk','vanity','dresser','heartmirror'].includes(id))return 'Vanities';if(['teddy','unicorn','cat'].includes(id))return 'Plushies';if(['lamp','sofabubble','sofamint','sofastar'].includes(id))return 'Sofas';if(['tree','swing','butterfly','flowers2','rainbow','pool','pineapple'].includes(id))return 'Outdoor';if(id.startsWith('birthday'))return 'Birthday';if(['sponge','jellyfish','seastar','bubbles'].includes(id))return 'Undersea';if(['pinkcurtains','fairylights','pinkflowers','sparklerug','bow'].includes(id))return 'Girly';return 'Decor'}
