function shopHtml(){const filtered=ITEMS.filter(it=>shopRoom==='party'?['Birthday','Undersea','Girly'].includes(itemType(it)): (it[4]===shopRoom||it[4]==='any')&&itemType(it)===shopType);const fridgeUnlocked=ownedItem('fridge');const visible=filtered.filter(it=>shopFilter==='affordable'?!ownedItem(it[0])&&coins>=it[3]:shopFilter==='unowned'?!ownedItem(it[0]):true).sort((a,b)=>Number(ownedItem(a[0]))-Number(ownedItem(b[0]))||a[3]-b[3]);return `<section class="panel"><h2 class="sectiontitle">🛍️ Dream Dollhouse Boutique</h2><p class="subtle">First pick a room, then choose what to shop for. Your purchases stay yours forever! 🌷</p><div class="house-banner">🪙 ${coins} coins · 🎁 ${owned.length} owned · ${ITEMS.filter(it=>!ownedItem(it[0])&&coins>=it[3]).length} affordable items</div><button type="button" class="primary" id="rkShopDecorate">🏠 Decorate my room →</button><h3>1. Pick a room 🏠</h3><div class="shop-categories">${[...ROOMS.map(r=>[r.id,r.icon+' '+r.name]),['party','🎉 Themes & parties']].map(([id,name])=>`<button class="${shopRoom===id?'active':''}" data-shop-room="${id}">${name}</button>`).join('')}</div><h3>2. Pick a collection 🎀</h3><div class="shop-categories subcats">${CATEGORIES[shopRoom].map(t=>`<button class="${shopType===t?'active':''}" data-shop-type="${t}" ${t==='Fridge Food'&&!fridgeUnlocked?'disabled aria-label="Fridge Food unlocks after buying a fridge"':''}>${t==='Fridge Food'&&!fridgeUnlocked?'🔒 ':''}${t}</button>`).join('')}</div>${shopRoom==='kitchen'&&!fridgeUnlocked?'<p class="house-help">🧊 Buy a fridge to unlock little food and treats for it!</p>':''}<h3>3. Choose your treasure ✨</h3><div class="shop-categories subcats"><button data-shop-filter="all" class="${shopFilter==='all'?'active':''}">🌈 Show all</button><button data-shop-filter="affordable" class="${shopFilter==='affordable'?'active':''}">🪙 I can buy</button><button data-shop-filter="unowned" class="${shopFilter==='unowned'?'active':''}">🎁 Not collected yet</button></div><p id="shopPurchaseNotice" class="house-help" role="status" aria-live="polite" hidden></p><div class="shop-grid">${visible.map(it=>`<div class="shop-item ${ownedItem(it[0])?'owned':''}"><div class="pic">${furnitureArt(it)}</div><div class="name">${esc(it[2])}</div><button type="button" data-preview="${it[0]}" aria-label="Preview ${esc(it[2])}" style="margin:5px auto;display:block">👀 Preview</button><div class="price">${ownedItem(it[0])?'✓ Owned':'🪙 '+it[3]+' coins'}</div><button data-buy="${it[0]}" ${ownedItem(it[0])||coins<it[3]?'disabled':''}>${ownedItem(it[0])?'Owned':coins<it[3]?'Not enough coins':'Buy'}</button></div>`).join('')}</div>${visible.length?'':'<p class="house-help">Nothing here yet! Try Show all or another collection. 🌸</p>'}</section>`}
function bindShop(){const quick=document.getElementById('rkShopDecorate');if(quick)quick.onclick=()=>{housePage='decorate';selectedItem='';houseRender()};document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const it=ITEMS.find(x=>x[0]===b.dataset.preview);if(!it)return;document.getElementById('rkShopPreview')?.remove();const shade=document.createElement('div');shade.id='rkShopPreview';shade.setAttribute('role','dialog');shade.setAttribute('aria-modal','true');shade.setAttribute('aria-label','Furniture preview');shade.style.cssText='position:fixed;inset:0;z-index:99999;background:#24112cbb;display:grid;place-items:center;padding:16px';const panel=document.createElement('div');panel.style.cssText='background:#fff9fc;color:#34243c;border-radius:24px;padding:24px;max-width:360px;width:100%;text-align:center;box-shadow:0 16px 45px #24112c66';const art=document.createElement('div');art.className='pic';art.style.cssText='min-height:150px;display:grid;place-items:center';art.innerHTML=furnitureArt(it);panel.appendChild(art);const title=document.createElement('h2');title.textContent=it[2];panel.appendChild(title);const info=document.createElement('p');info.textContent=ownedItem(it[0])?'✓ You already own this item':'🪙 '+it[3]+' coins · '+(coins>=it[3]?'You can afford it':'Save up '+(it[3]-coins)+' more coins');panel.appendChild(info);const close=document.createElement('button');close.type='button';close.className='primary';close.textContent='← Back to shopping';close.onclick=()=>{shade.remove();b.focus()};panel.appendChild(close);shade.appendChild(panel);shade.addEventListener('click',e=>{if(e.target===shade)close.click()});document.body.appendChild(shade);close.focus();});document.querySelectorAll('[data-shop-filter]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shopFilter;audio('tap');houseRender()});document.querySelectorAll('[data-shop-room]').forEach(b=>b.onclick=()=>{shopRoom=b.dataset.shopRoom;shopType=CATEGORIES[shopRoom][0];audio('tap');houseRender()});document.querySelectorAll('[data-shop-type]').forEach(b=>b.onclick=()=>{shopType=b.dataset.shopType;audio('tap');houseRender()});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const it=ITEMS.find(x=>x[0]===b.dataset.buy);if(!it||ownedItem(it[0])||coins<it[3])return;coins-=it[3];owned.push(it[0]);saveHouse();try{localStorage.setItem('rickyCoins',coins)}catch{}audio('win');celebrate();updateStats();housePage='shop';houseMessage=`🎁 ${it[2]} added to your furniture!`;const scrollY=window.scrollY;houseRender();window.scrollTo(0,scrollY);const notice=document.querySelector('#shopPurchaseNotice');if(notice){notice.textContent=`✓ Bought ${it[2]}! Keep shopping, or tap Decorate when you're ready.`;notice.hidden=false;}})}
