function decorateHtml(){const r=roomData(),placements=decor[currentRoom]||{},usable=ITEMS.filter(it=>ownedItem(it[0])&&canUse(it,currentRoom));return `<section class="panel"><h2 class="sectiontitle">🎨 Decorate your ${r.name.toLowerCase()}</h2><div class="room-tabs">${ROOMS.map(room=>`<button data-room="${room.id}" class="${currentRoom===room.id?'active':''}">${room.icon} ${room.name}</button>`).join('')}</div><div class="house-stage ${currentRoom}" style="--wall:${wallColors[currentRoom]||r.wall};--floor:${r.floor}"><div class="house-window"></div><div class="house-rug"></div>${SLOTS.map((slot,i)=>`<button class="house-slot ${selectedItem?'ready':''}" data-slot="${i}" style="left:${slot.x}%;top:${slot.y}%" aria-label="Decorate spot ${i+1}"></button>${placements[i]?`<button class="house-item ${selectedItem===placements[i]?'selected':''}" data-item-slot="${i}" style="left:${slot.x}%;top:${slot.y}%" title="Move or remove ${ITEMS.find(it=>it[0]===placements[i])?.[2]||''}">${furnitureArt(ITEMS.find(it=>it[0]===placements[i])||ITEMS[0])}</button>`:''}`).join('')}</div><p class="house-help">${houseMessage||'Choose an item below, then tap a dotted spot in the room to place it. Tap furniture to pick it up or move it.'}</p><h3>🎁 Your furniture collection</h3>${usable.length?`<div class="inventory">${usable.map(it=>`<button data-select="${it[0]}" class="${selectedItem===it[0]?'active':''}" title="${esc(it[2])}">${furnitureArt(it)} <span class="tiny">${esc(it[2])}</span></button>`).join('')}</div>`:'<div class="house-banner">Your room is waiting for furniture! Visit the shop to buy your first piece. 🛍️</div>'}<div class="row" style="justify-content:center;margin-top:15px"><button class="secondary" id="moveItem" ${!selectedItem?'disabled':''}>↔️ Move</button><button class="secondary" id="removeItem" ${!selectedItem?'disabled':''}>📦 Put Away</button><button class="secondary" id="clearDecorSelection" ${!selectedItem?'disabled':''}>✕ Deselect</button><button class="primary" id="goShop">🛍️ Shop for more</button></div><h3>🎨 Choose a wall color</h3><div class="decor-options">${[['#fbe3f4','🌸 Pink'],['#e3e0ff','💜 Lavender'],['#d9f6ed','🌿 Mint'],['#d7f6ff','🩵 Sky'],['#fff0cb','☀️ Cream']].map(([c,label])=>`<button data-wall="${c}" class="${(wallColors[currentRoom]||r.wall)===c?'active':''}">${label}</button>`).join('')}</div></section>`}
function bindDecor(){document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{currentRoom=b.dataset.room;selectedItem='';houseMessage='';audio('tap');houseRender()});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedItem=b.dataset.select;houseMessage='Tap a dotted spot in the room to place '+ITEMS.find(it=>it[0]===selectedItem)[2]+'.';audio('tap');houseRender()});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{if(!selectedItem){houseMessage='Choose a piece of furniture below first!';audio('bad');houseRender();return}const slot=b.dataset.slot;const placements=decor[currentRoom]||{};for(const k of Object.keys(placements))if(placements[k]===selectedItem)delete placements[k];placements[slot]=selectedItem;decor[currentRoom]=placements;saveHouse();audio('good');houseMessage='✨ Beautiful! Pick another item or try a different room.';selectedItem='';houseRender()});document.querySelectorAll('[data-item-slot]').forEach(b=>b.onclick=()=>{const slot=b.dataset.itemSlot;const placements=decor[currentRoom]||{};selectedItem=placements[slot];houseMessage='Selected! Tap Move, then a dotted spot, or Put Away to return it to your collection.';audio('tap');houseRender()});$('#moveItem').onclick=()=>{if(!selectedItem)return;houseMessage='↔️ Tap a dotted spot to move this item.';audio('tap');houseRender()};$('#clearDecorSelection').onclick=()=>{selectedItem='';houseMessage='Choose furniture to place, or tap an item to move it.';houseRender()};$('#removeItem').onclick=()=>{if(!selectedItem)return;const placements=decor[currentRoom]||{};for(const k of Object.keys(placements))if(placements[k]===selectedItem)delete placements[k];saveHouse();selectedItem='';houseMessage='Item returned to your collection — you still own it!';audio('tap');houseRender()};$('#goShop').onclick=()=>{housePage='shop';audio('tap');houseRender()};document.querySelectorAll('[data-wall]').forEach(b=>b.onclick=()=>{wallColors[currentRoom]=b.dataset.wall;saveHouse();audio('good');houseRender()})}

function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function ids(){return mode==='new'?Array.from({length:12},(_,i)=>i+26):mode==='old'?Array.from({length:26},(_,i)=>i):Array.from({length:38},(_,i)=>i)}
function topSettings(){return `<div class="panel settings"><label for="set">📚 Word set</label><select id="set"><option value="new" ${mode==='new'?'selected':''}>New 12 words</option><option value="old" ${mode==='old'?'selected':''}>Original 26 words</option><option value="all" ${mode==='all'?'selected':''}>All 38 words</option></select><span class="subtle">No stressful countdowns. Take your time! 💜</span></div>`}
function menu(){game='';session=null;app.innerHTML=`<section class="hero"><div class="spark">🦄 🌟 🦋</div><h1>Pick your adventure!</h1><p>Six different games, magical rewards, and new surprises every round. Which challenge will you conquer?</p></section>${topSettings()}<section class="panel"><h2 class="sectiontitle">🎮 Choose a game</h2><div class="games">${[['detective','🔎','Mystery Detective','Read clues and solve the Hebrew mystery.','Think & solve'],['memory','🃏','Magic Memory','Flip cards and find matching pairs.','Remember & match'],['bubbles','🫧','Bubble Pop','Pop the bubble with the right meaning.','Quick & playful'],['builder','🧩','Letter Builder','Build the Hebrew shoresh letter by letter.','Spell & create'],['sort','🚀','Rocket Launch','Pick the Hebrew root to launch your rocket.','Reverse challenge'],['wheel','🎡','Spin the Word Wheel','Spin to practice prefixes, suffixes, and Hebrew word parts.','Spin & discover']].map(g=>`<button class="gamecard" data-game="${g[0]}"><span class="emoji">${g[1]}</span><strong>${g[2]}</strong><p>${g[3]}</p><span class="tag">${g[4]}</span></button>`).join('')}</div></section><section class="panel" style="text-align:center"><h2>🏠 Your Dream Dollhouse</h2><div class="reward"><span>💎</span><span>👑</span><span>🌈</span></div><p>Play Shoresh games to earn coins, then shop for furniture and decorate your own dollhouse!</p><strong>🪙 ${coins} coins available</strong><p><button class="primary" id="visitHouse">🏠 Visit my dollhouse!</button></p></section>`;$('#set').onchange=e=>{mode=e.target.value;audio('tap')};document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>start(b.dataset.game));$('#visitHouse').onclick=houseHome}
function frame(title,body,progress=''){app.innerHTML=`<section class="panel"><div class="gamehead"><button class="secondary" id="home">← Game menu</button><strong>${title}</strong><span class="pill">${session?.score||0} ⭐</span></div>${progress?`<div class="progress"><div style="width:${progress}%"></div></div>`:''}${body}</section>`;$('#home').onclick=()=>{audio('tap');menu()}}
function start(g){audio('tap');game=g;round++;const all=shuffle(ids());const count=g==='memory'?Math.min(6,all.length):g==='builder'?Math.min(8,all.length):Math.min(10,all.length);session={order:all.slice(0,count),at:0,score:0,missed:[],done:false,locked:false,hint:0,attempt:0,flip:[],matched:[],pairCount:0,letters:[],chosen:[],tries:0};if(g==='memory')prepareMemory();if(g==='wheel'){session.wheelPhase='ready';session.wheelRotation=0;session.wheelQuestion=null;session.wheelTotal=0;session.wheelResult='';session.wheelLock=false;session.wheelCategory='';session.wheelSpins=0}render()}
function advance(){session.at++;session.locked=false;session.hint=0;session.attempt=0;session.chosen=[];session.tries=0;if(session.at>=session.order.length){finish();return}render()}
function correct(points=3){audio('good');streak++;session.score+=points;award(points*2);updateStats()}
function incorrect(){audio('bad');streak=0;updateStats();const id=session.order[session.at];if(!session.missed.includes(id))session.missed.push(id)}
function finish(){audio('win');celebrate();const count=session.order.length;frame('🎉 Adventure complete!',`<div class="end"><div class="big">🏆</div><h2>Fantastic effort, Riki!</h2><p>You finished <strong>${count}</strong> words!</p><div class="reward"><span>🌟</span><span>💎</span><span>🎀</span></div><h2>${session.score} stars earned</h2><p>🪙 Your treasure vault has <strong>${coins}</strong> coins.</p><p class="subtle">${(()=>{const next=ITEMS.filter(it=>!ownedItem(it[0])&&it[3]>0).sort((a,b)=>a[3]-b[3])[0];return next?(coins>=next[3]?'🎁 You can afford a new item right now!':'✨ Only '+(next[3]-coins)+' more coins until your next furniture reward!'):'🌈 Your furniture collection is complete!'})()}</p><p><button class="primary" id="houseAfter">🛍️ Spend coins at my dollhouse!</button></p>${session.missed.length?`<div class="hintbox">💡 Keep practicing: ${session.missed.map(i=>`<span dir="rtl">${W[i][0]}</span> (${W[i][1]})`).join(' · ')}</div>`:'<div class="feedback good">✨ You solved every word without a wrong answer!</div>'}<div class="row" style="justify-content:center"><button class="primary" id="again">🔁 Play again</button><button class="secondary" id="tomenu">🎮 Game menu</button></div></div>`,'100');$('#again').onclick=()=>start(game);$('#tomenu').onclick=menu;$('#houseAfter').onclick=()=>{housePage='shop';houseMessage='🎉 Great playing! Pick something you love, then decorate whenever you are ready.';houseRender();window.scrollTo({top:0,behavior:'smooth'})}}
function render(){if(game==='detective')detective();if(game==='memory')memory();if(game==='bubbles')bubbles();if(game==='builder')builder();if(game==='sort')sort();if(game==='wheel')wheel()}
function optionsFor(id,n=4,reverse=false){const arr=shuffle(ids().filter(i=>i!==id&&(reverse||W[i][1]!==W[id][1])));const chosen=[];for(const i of arr){if(reverse||!chosen.some(j=>W[j][1]===W[i][1]))chosen.push(i);if(chosen.length>=n-1)break}return shuffle([id,...chosen])}
function detective(){const s=session,id=s.order[s.at],w=W[id],opts=s.opts||(s.opts=optionsFor(id));frame('🔎 Mystery Detective',`<p class="subtle">Mystery ${s.at+1} / ${s.order.length} · Earn up to 3 stars!</p><div class="prompt"><div class="eyebrow">🕵️ WHO AM I?</div><div class="meaning">${esc(w[1])}</div><p>Find the matching Hebrew shoresh!</p>${s.hint>0?`<div class="hintbox">💡 ${esc(w[2])}</div>`:''}${s.hint>1?`<div class="hintbox">🔤 Starts with <strong dir="rtl">${w[0][0]}</strong></div>`:''}</div><div class="options">${opts.map(i=>`<button class="option he" data-choice="${i}" ${s.locked?'disabled':''}>${W[i][0]}</button>`).join('')}</div><div id="result"></div><div class="foot"><button class="secondary" id="clue" ${s.hint>=2||s.locked?'disabled':''}>💡 ${s.hint?'Another clue':'Give me a clue'}</button><span class="subtle">Hints are always okay!</span></div>`,100*s.at/s.order.length);$('#clue').onclick=()=>{s.hint++;audio('tap');detective()};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(s.locked)return;const picked=Number(b.dataset.choice);if(picked===id){s.locked=true;correct(Math.max(1,3-s.hint));b.classList.add('correct');document.querySelectorAll('[data-choice]').forEach(x=>x.disabled=true);$('#result').innerHTML=`<div class="feedback good">🌟 Mystery solved! ${w[0]} = ${esc(w[1])}</div><button class="primary" id="next">Next mystery →</button>`;$('#next').onclick=()=>{if(session!==s)return;s.opts=null;advance()};const answerIndex=s.at;setTimeout(()=>{const next=document.getElementById('next');if(session===s&&s.at===answerIndex&&next&&next.isConnected)next.click()},1100)}else{incorrect();b.classList.add('wrong');b.disabled=true;$('#result').innerHTML=`<div class="feedback try">💜 Not this one. Try another root!</div>`}})}
function prepareMemory(){const s=session;s.pairs=s.order.map((id,k)=>[{id,kind:'he',key:k},{id,kind:'en',key:k}]).flat();s.cards=shuffle(s.pairs);s.flip=[];s.matched=[];s.pairCount=0}
function memory(){const s=session;frame('🃏 Magic Memory',`<p class="subtle">Find all ${s.order.length} pairs · Match a Hebrew word to its English meaning</p><div class="progress"><div style="width:${s.pairCount/s.order.length*100}%"></div></div><div class="memory">${s.cards.map((c,i)=>{const open=s.flip.includes(i)||s.matched.includes(c.key);return `<button class="tile ${open?'open':''} ${s.matched.includes(c.key)?'matched':''}" data-tile="${i}" ${s.matched.includes(c.key)?'disabled':''}>${open?`<span class="${c.kind==='he'?'he':'tiny'}">${esc(c.kind==='he'?W[c.id][0]:(c.id===17?'Tell (a story)':c.id===4?'Tell (someone)':W[c.id][1]))}</span>`:'✨'}</button>`}).join('')}</div><p class="subtle">Pairs found: ${s.pairCount} / ${s.order.length}</p><div id="memmessage" class="feedback" style="display:none"></div>`,s.pairCount/s.order.length*100);document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.tile);if(s.locked||s.flip.includes(i)||s.matched.includes(s.cards[i].key))return;s.flip.push(i);audio('tap');b.classList.add('open');const c=s.cards[i];b.innerHTML=`<span class="${c.kind==='he'?'he':'tiny'}">${esc(c.kind==='he'?W[c.id][0]:(c.id===17?'Tell (a story)':c.id===4?'Tell (someone)':W[c.id][1]))}</span>`;if(s.flip.length===2){const [a,z]=s.flip.map(j=>s.cards[j]);if(a.key===z.key){s.matched.push(a.key);s.pairCount++;correct(2);s.flip=[];setTimeout(()=>{if(game!=='memory'||session!==s)return;if(s.pairCount===s.order.length)finish();else memory()},450)}else{s.locked=true;incorrect();$('#memmessage').style.display='block';$('#memmessage').textContent='Look closely and remember where the cards are!';setTimeout(()=>{if(game!=='memory'||session!==s)return;s.flip=[];s.locked=false;memory()},1050)}}})}
function bubbles(){const s=session,id=s.order[s.at],w=W[id];s.opts=s.opts||optionsFor(id,3);frame('🫧 Bubble Pop',`<p class="subtle">Bubble ${s.at+1} / ${s.order.length}</p><div class="prompt"><div class="eyebrow">🫧 POP THE RIGHT MEANING!</div><div class="hebrew">${w[0]}</div></div><div class="bubblefield">${s.opts.map((i,k)=>`<button class="bubble" data-bubble="${i}" style="background-color:${['#ffd0e8','#c3eaff','#d8cbff'][k]}" ${s.locked?'disabled':''}>${esc(W[i][1])}</button>`).join('')}</div><div id="result"></div><div class="foot"><button class="secondary" id="hint">💡 Show memory clue</button><span class="subtle">Pop and collect stars!</span></div>`,100*s.at/s.order.length);$('#hint').onclick=()=>{$('#result').innerHTML=`<div class="hintbox">${esc(w[2])}</div>`;audio('tap')};document.querySelectorAll('[data-bubble]').forEach(b=>b.onclick=()=>{if(s.locked)return;const pick=Number(b.dataset.bubble);if(pick===id){s.locked=true;correct(3);b.classList.add('pop');$('#result').innerHTML=`<div class="feedback good">POP! 🎉 ${w[0]} means ${esc(w[1])}!</div><button class="primary" id="next">Next bubbles →</button>`;$('#next').onclick=()=>{if(session!==s)return;s.opts=null;advance()};const answerIndex=s.at;setTimeout(()=>{const next=document.getElementById('next');if(session===s&&s.at===answerIndex&&next&&next.isConnected)next.click()},1100)}else{incorrect();b.classList.add('wrong');b.disabled=true;$('#result').innerHTML='<div class="feedback try">Oops! That bubble was a decoy. Try again! 💜</div>'}})}
function builder(){const s=session,id=s.order[s.at],w=W[id];if(!s.letters.length){s.letters=shuffle([...w[0]].map((ch,i)=>({ch,i})));s.chosen=[]}const built=s.chosen.map(i=>s.letters[i].ch).join('');const right=built===w[0];frame('🧩 Letter Builder',`<p class="subtle">Build ${s.at+1} / ${s.order.length} · Tap letters in Hebrew reading order (right to left)</p><div class="prompt"><div class="eyebrow">BUILD THE SHORESH FOR:</div><div class="meaning">${esc(w[1])}</div></div><div class="buildslots" dir="rtl">${Array.from({length:w[0].length},(_,i)=>`<div class="slot">${esc(built[i]||'')}</div>`).join('')}</div><div class="letterbank" dir="rtl">${s.letters.map((l,i)=>`<button class="letter" data-letter="${i}" ${s.chosen.includes(i)||s.locked?'disabled':''}>${l.ch}</button>`).join('')}</div><div id="result">${s.hint?`<div class="hintbox">💡 ${esc(w[2])} · First letter: <strong>${w[0][0]}</strong></div>`:''}</div><div class="foot"><button class="secondary" id="undo" ${!s.chosen.length||s.locked?'disabled':''}>↶ Undo</button><button class="secondary" id="hint">💡 Hint</button><button class="secondary" id="clear" ${!s.chosen.length||s.locked?'disabled':''}>Clear</button></div>`,100*s.at/s.order.length);$('#undo').onclick=()=>{s.chosen.pop();audio('tap');builder()};$('#clear').onclick=()=>{s.chosen=[];audio('tap');builder()};$('#hint').onclick=()=>{s.hint=1;audio('tap');builder()};document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{if(s.locked)return;s.chosen.push(Number(b.dataset.letter));audio('tap');const attempt=s.chosen.map(i=>s.letters[i].ch).join('');if(s.chosen.length===w[0].length){if(attempt===w[0]){s.locked=true;correct(s.tries?1:4);builder();$('#result').innerHTML=`<div class="feedback good">🧩 You built it! ${w[0]} = ${esc(w[1])}</div><button class="primary" id="next">Next puzzle →</button>`;$('#next').onclick=()=>{if(session!==s)return;s.letters=[];advance()};const answerIndex=s.at;setTimeout(()=>{const next=document.getElementById('next');if(session===s&&s.at===answerIndex&&next&&next.isConnected)next.click()},1100)}else{s.tries++;incorrect();s.chosen=[];builder();$('#result').innerHTML='<div class="feedback try">Not quite! Try the letters in a different order. 💜</div>'}}else builder()})}
function sort(){const s=session,id=s.order[s.at],w=W[id];s.opts=s.opts||optionsFor(id,4,true);frame('🚀 Rocket Launch',`<p class="subtle">Launch ${s.at+1} / ${s.order.length}</p><div class="prompt"><div style="font-size:56px">🚀</div><div class="eyebrow">FUEL YOUR ROCKET WITH THE RIGHT SHORESH!</div><div class="meaning">${esc(w[1])}</div></div><div class="options">${s.opts.map(i=>`<button class="option he" data-choice="${i}" ${s.locked?'disabled':''}>${W[i][0]}</button>`).join('')}</div><div id="result"></div><div class="foot"><button class="secondary" id="hint">💡 Fuel hint</button><span class="subtle">Choose the right root to launch!</span></div>`,100*s.at/s.order.length);$('#hint').onclick=()=>{$('#result').innerHTML=`<div class="hintbox">💡 ${esc(w[2])}</div>`;audio('tap')};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(s.locked)return;const pick=Number(b.dataset.choice);if(pick===id){s.locked=true;correct(3);b.classList.add('correct');$('#result').innerHTML=`<div class="feedback good" style="font-size:25px">🚀 WHOOSH! Great launch! 🌟</div><button class="primary" id="next">Launch again →</button>`;$('#next').onclick=()=>{if(session!==s)return;s.opts=null;advance()};const answerIndex=s.at;setTimeout(()=>{const next=document.getElementById('next');if(session===s&&s.at===answerIndex&&next&&next.isConnected)next.click()},1100)}else{incorrect();b.classList.add('wrong');b.disabled=true;$('#result').innerHTML='<div class="feedback try">That fuel does not fit. Try another shoresh! 💜</div>'}})}

// The wheel teaches grammatical word parts, not just bare root translations.
// Prefixes are practiced on recognizable words; suffixes are shown on simple nouns.
const PREFIXES=[
 {a:'ו',meaning:'And',word:'ושלח',base:'שלח',explain:'ו at the front often means AND. ושלח = and sent.'},
 {a:'ב',meaning:'In / At',word:'בבית',base:'בית',explain:'ב at the front often means IN or AT. בבית = in the house.'},
 {a:'ל',meaning:'To / For',word:'לבית',base:'בית',explain:'ל at the front often means TO or FOR. לבית = to the house.'},
 {a:'מ',meaning:'From',word:'מבית',base:'בית',explain:'מ at the front often means FROM. מבית = from a house.'},
 {a:'כ',meaning:'Like / As',word:'כמלך',base:'מלך',explain:'כ at the front often means LIKE or AS. כמלך = like a king.'},
 {a:'ה',meaning:'The',word:'הבית',base:'בית',explain:'ה at the front often means THE. הבית = the house.'},
 {a:'ש',meaning:'That / Which',word:'שאמר',base:'אמר',explain:'ש at the front can mean THAT. שאמר = that he said.'}
];
const SUFFIXES=[
 {a:'י',meaning:'My',word:'ספרי',base:'ספר',explain:'י at the end of a noun can mean MY. ספרי = my book.'},
 {a:'ו',meaning:'His',word:'ספרו',base:'ספר',explain:'ו at the end of a noun can mean HIS. ספרו = his book.'},
 {a:'ה',meaning:'Her',word:'ספרה',base:'ספר',explain:'ה at the end of a noun can mean HER. ספרה = her book.'},
 {a:'נו',meaning:'Our',word:'ספרנו',base:'ספר',explain:'נו at the end of a noun can mean OUR. ספרנו = our book.'},
 {a:'ם',meaning:'Their',word:'ספרם',base:'ספר',explain:'ם at the end of a noun can mean THEIR (masculine plural). ספרם = their book.'},
 {a:'ך',meaning:'Your',word:'ספרך',base:'ספר',explain:'ך at the end of a noun can mean YOUR. The vowel changes depending on who is addressed.'}
];
const PARTS=['And','In / At','To / For','From','Like / As','The','That / Which','My','His','Her','Our','Their','Your'];
const WHEEL_SEGMENTS=[['🔗 AND','prefix',0],['🌸 PREFIX','prefix',1],['🎀 SUFFIX','suffix',0],['💎 ENDINGS','suffix',1],['🌈 MIX IT','mixed',0],['⭐ BONUS','mixed',1]];
function pickWheelQuestion(category){const list=category==='prefix'?PREFIXES:category==='suffix'?SUFFIXES:[...PREFIXES,...SUFFIXES];const obj=list[Math.floor(Math.random()*list.length)],type=PREFIXES.includes(obj)?'prefix':'suffix';let opts=shuffle([obj.meaning,...shuffle(PARTS.filter(x=>x!==obj.meaning)).slice(0,3)]);return {...obj,type,opts}}
function wheel(){const s=session;let isReady=s.wheelPhase==='ready',isSpinning=s.wheelPhase==='spinning',q=s.wheelQuestion;frame('🎡 Spin the Word Wheel',`<div class="wheel-layout"><div><div class="wheel-wrap"><div class="wheel-pointer">▼</div><div class="wheel" id="wordWheel" style="transform:rotate(${s.wheelRotation}deg)">${WHEEL_SEGMENTS.map((x,i)=>`<span class="wheel-label" style="transform:rotate(${-s.wheelRotation}deg)">${x[0]}</span>`).join('')}</div></div><div style="text-align:center;margin-top:17px"><span class="wheel-tag">🎯 ${s.wheelSpins} spins · ⭐ ${s.score} stars</span></div></div><div>${isReady||isSpinning?`<div class="wheel-question"><div style="font-size:48px">🎡✨</div><h2>${isSpinning?'Where will it land?':'Spin for your next Hebrew challenge!'}</h2><p>Practice prefixes (letters at the front) and suffixes (letters at the end). Every correct answer earns coins for your dollhouse!</p><button class="primary" id="spinButton" ${isSpinning?'disabled':''}>${isSpinning?'🎠 Spinning…':'🎡 SPIN THE WHEEL!'}</button></div>`:`<div class="wheel-question"><span class="wheel-tag">${q.type==='prefix'?'🌸 Prefix at the FRONT':'🎀 Suffix at the END'}</span><div class="partword"><span class="${q.type==='prefix'?'affix':'stem'}" dir="rtl">${esc(q.type==='prefix'?q.a:q.base)}</span><span class="${q.type==='suffix'?'suffix':'stem'}" dir="rtl">${esc(q.type==='suffix'?q.a:q.base)}</span></div><p style="font-size:17px;font-weight:800">What does the highlighted <strong>${q.type==='prefix'?'beginning':'ending'}</strong> mean?</p><div class="wheel-answer">${q.opts.map((o,i)=>`<button data-wheel-answer="${i}" class="${s.wheelResult&&o===q.meaning?'correct':''} ${s.wheelResult==='wrong'&&s.wheelPicked===o?'wrong':''}" ${s.wheelLock?'disabled':''}>${esc(o)}</button>`).join('')}</div>${s.wheelResult?`<div class="wheel-info"><strong>${s.wheelResult==='correct'?'🌟 Correct!':'💜 Good try!'} ${esc(q.meaning)}</strong><p>${esc(q.explain)}</p></div><button class="primary" id="spinAgain">🎡 Spin again!</button>`:`<p class="subtle">💡 The colorful part is the clue. No timer!</p>`}</div>`}</div></div><div class="wheel-info"><strong>🧠 Hebrew word trick:</strong> The same letter can mean different things depending on where it appears. <strong>ו</strong> at the beginning often means <strong>and</strong>, while <strong>ו</strong> at the end of a noun can mean <strong>his</strong>. These are beginner examples; word endings also change in verbs.</div><div class="row" style="justify-content:center"><button class="secondary" id="wheelHouse">🏠 Spend my coins</button><button class="secondary" id="wheelMenu">🎮 Other games</button></div>`,Math.min(100,s.wheelSpins*10));$('#wheelHouse').onclick=houseHome;$('#wheelMenu').onclick=menu;
if(isReady){$('#spinButton').onclick=()=>{if(s.wheelPhase!=='ready')return;audio('tap');s.wheelPhase='spinning';s.wheelResult='';const slot=Math.floor(Math.random()*6);s.wheelCategory=WHEEL_SEGMENTS[slot][1];s.wheelQuestion=pickWheelQuestion(s.wheelCategory);const from=s.wheelRotation;const to=from+1800+((6-slot)%6)*60+30-(from%360);s.wheelSpins++;s.wheelRotation=from;wheel();const disc=document.getElementById('wordWheel');if(disc){disc.style.transition='none';disc.style.transform=`rotate(${from}deg)`;requestAnimationFrame(()=>requestAnimationFrame(()=>{disc.style.transition='transform 3.5s cubic-bezier(.12,.75,.12,1)';disc.style.transform=`rotate(${to}deg)`;}))}s.wheelRotation=to;setTimeout(()=>{if(game!=='wheel'||session!==s||s.wheelPhase!=='spinning')return;s.wheelPhase='question';audio('win');wheel()},3550)}}
if(q&&!isReady&&!isSpinning){document.querySelectorAll('[data-wheel-answer]').forEach(b=>b.onclick=()=>{if(s.wheelLock)return;const picked=q.opts[Number(b.dataset.wheelAnswer)];s.wheelPicked=picked;s.wheelResult=picked===q.meaning?'correct':'wrong';s.wheelLock=true;if(s.wheelResult==='correct'){correct(4);celebrate()}else incorrectWheel();wheel()});if(s.wheelResult)$('#spinAgain').onclick=()=>{s.wheelPhase='ready';s.wheelLock=false;s.wheelQuestion=null;s.wheelResult='';audio('tap');wheel()}}
}
