function updateMusicControls(){const b=document.getElementById('musicToggle'),v=document.getElementById('volumeValue');if(b){b.textContent=musicPrefs.on?'♫ Music on':'♪ Music off';b.setAttribute('aria-pressed',String(musicPrefs.on))}if(v)v.textContent=musicPrefs.volume+'%'}
function note(freq,at,duration,pan=0,amp=1){if(!musicContext)return;const o=musicContext.createOscillator(),gain=musicContext.createGain(),filter=musicContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1200;o.type='sine';o.frequency.setValueAtTime(freq,at);gain.gain.setValueAtTime(.00001,at);const peak=Math.min(.22,musicPrefs.volume/100*.22)*amp;gain.gain.linearRampToValueAtTime(Math.max(.00002,peak),at+.09);gain.gain.exponentialRampToValueAtTime(.00001,at+duration);o.connect(filter);filter.connect(gain);if(typeof musicContext.createStereoPanner==='function'){const p=musicContext.createStereoPanner();p.pan.setValueAtTime(Math.max(-.85,Math.min(.85,pan)),at);gain.connect(p);p.connect(musicContext.destination)}else gain.connect(musicContext.destination);o.start(at);o.stop(at+duration+.02);musicNodes.push(o);o.onended=()=>{musicNodes=musicNodes.filter(n=>n!==o);o.disconnect();gain.disconnect();filter.disconnect()}}
function musicTick(){if(!musicPrefs.on||musicPrefs.volume===0||document.hidden||!musicContext||musicContext.state!=='running')return;const seq=tracks[game]||tracks.menu,step=musicStep++,pitch=seq[step%seq.length],now=musicContext.currentTime+.03,pan=Math.sin(step*.43)*.72;note(261.63*Math.pow(2,pitch/12),now,.55,pan,.85);if(step%4===0)note(130.81*Math.pow(2,seq[step%seq.length]/12),now,1.05,-pan*.45,.42)}
function startMusic(){if(!musicPrefs.on||musicPrefs.volume===0||document.hidden)return;try{musicContext=musicContext||new(window.AudioContext||window.webkitAudioContext)();const begin=()=>{if(!musicPrefs.on||document.hidden||musicPrefs.volume===0||musicContext.state!=='running'||musicTimer)return;musicTick();musicTimer=setInterval(musicTick,470)};if(musicContext.state==='running')begin();else musicContext.resume().then(begin).catch(()=>{});}catch(e){console.warn('Background music unavailable',e)}}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}for(const o of musicNodes){try{o.stop()}catch{}}musicNodes=[]}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMusic();else if(musicPrefs.on)startMusic()});
// Music can only start after a user interaction. No surprise autoplay.
document.addEventListener('pointerdown',()=>{if(musicPrefs.on&&!musicTimer)startMusic()},{passive:true});
function level(){return 1+Math.floor(adventureXP/80)}
function questHTML(){const l=level(),p=adventureXP%80;const islands=[['🌷','Flower Field'],['🧁','Cupcake Cove'],['🐚','Ocean Bay'],['🎠','Rainbow Fair'],['🏰','Dream Castle']];return `<section class="quest-map" aria-label="Adventure progress"><h2>🗺️ Riki's Learning Adventure</h2><p>Level <strong>${l}</strong> · <strong>${adventureXP}</strong> XP · Keep practicing to reach the next world!</p><div class="quest-track" role="progressbar" aria-valuemin="0" aria-valuemax="80" aria-valuenow="${p}"><div class="quest-fill" style="width:${p/80*100}%"></div></div><div class="quest-reward">🌟 ${80-p} XP until Level ${l+1}</div><div class="quest-islands">${islands.map((is,i)=>`<div class="quest-island ${l>=i+1?'unlocked':'locked'}"><span class="island-icon">${is[0]}</span>${is[1]}</div>`).join('')}</div><p class="quest-hint">🎮 Every game is available right away. Levels unlock colorful world badges, not learning restrictions. Earn coins to shop in your dollhouse!</p></section>`}
const priorAward=award;
award=function(n){priorAward(n);adventureXP+=Math.max(1,Math.round(n));try{localStorage.setItem(XP_KEY,adventureXP)}catch{};if(adventureXP%80<Math.max(1,Math.round(n)))celebrate()};
const menuWithGames=menu;
menu=function(){menuWithGames();const hero=document.querySelector('.hero');if(hero){/* Adventure panel hidden; XP tracking and saved progress remain active. */const p=hero.querySelector('p');if(p)p.textContent='Choose your adventure, earn coins, collect XP, and decorate your dreamhouse!'}if(musicPrefs.on&&musicContext)startMusic()};
const priorFrame=frame;
frame=function(title,body,progress=''){priorFrame(title,body,progress);const head=document.querySelector('.gamehead');if(head)head.insertAdjacentHTML('afterend',`<div class="quest-hint" data-live-coins-summary style="text-align:center">🌟 Level ${level()} · 🎵 ${musicPrefs.on?'Gentle music on':'Turn on gentle music above'} · 🪙 ${coins} coins</div>`)};

// New creative worlds: no color-coding of correct pairs. Answers depend on Hebrew meanings.
const creativeMenu=menu;
menu=function(){creativeMenu();const grid=document.querySelector('.games');if(!grid)return;grid.insertAdjacentHTML('beforeend',`<button class="gamecard" data-creative="cupcakes"><span class="emoji">🧁</span><strong>Cupcake Café</strong><p>Match a cupcake order to its Hebrew topper and serve a customer!</p><span class="tag">Build & serve</span></button><button class="gamecard" data-creative="dressup"><span class="emoji">👗</span><strong>Dress-Up Studio</strong><p>Choose dresses, shoes and accessories by their Hebrew roots. Style a doll!</p><span class="tag">Fashion studio</span></button><button class="gamecard" data-creative="pets"><span class="emoji">🐱</span><strong>Pet Spa</strong><p>Decode the Hebrew instructions to pamper adorable pets!</p><span class="tag">Care & create</span></button>`);document.querySelectorAll('[data-creative]').forEach(b=>b.onclick=()=>start(b.dataset.creative))};
const creativeStart=start;
start=function(g){if(!['cupcakes','dressup','pets'].includes(g))return creativeStart(g);audio('tap');game=g;round++;const order=shuffle(ids()).slice(0,Math.min(8,ids().length));session={order,at:0,score:0,locked:false,tries:0,served:0,parts:[],stage:0,choice:null};render()};
const creativeRender=render;
render=function(){if(game==='cupcakes')return cupcakeGame();if(game==='dressup')return dressGame();if(game==='pets')return petGame();return creativeRender()};
function creativeDone(title,emoji){const s=session;frame(title,`<div class="creative-banner"><div class="bigscene">${emoji} 🏆 ✨</div><h2>YOU DID IT!</h2><p>You finished ${s.order.length} creative challenges!</p><h3>⭐ ${s.score} stars · 🪙 Coins earned for your dollhouse</h3><button class="primary" id="creativeAgain">🔁 Play again</button> <button class="secondary" id="creativeMenu">🎮 Choose another game</button></div>`);$('#creativeAgain').onclick=()=>start(game);$('#creativeMenu').onclick=menu;celebrate()}
function creativeAdvance(){const s=session;s.at++;s.locked=false;s.tries=0;s.stage=0;s.parts=[];s.choice=null;if(s.at>=s.order.length)creativeDone(({cupcakes:'🧁 Cupcake Café',dressup:'👗 Dress-Up Studio',pets:'🐱 Pet Spa'})[game],({cupcakes:'🧁',dressup:'👗',pets:'🐱'})[game]);else render()}
function creativeAnswer(correct,button,successText){const s=session;if(s.locked)return;if(correct){s.locked=true;s.score+=s.tries?2:5;award(s.tries?4:9);audio('good');button.classList.add('correct');celebrate();const f=$('#creativeFeedback');if(f)f.innerHTML=`<div class="feedback good sparkle-pop">${successText}</div><button class="primary" id="creativeNext">${s.at===s.order.length-1?'🎉 Finish':'Next customer →'}</button>`;$('#creativeNext').onclick=creativeAdvance}else{s.tries++;audio('bad');button.classList.add('wrong');button.disabled=true;const f=$('#creativeFeedback');if(f)f.innerHTML='<div class="feedback try">Almost! Try another one. You can do it! 💜</div>'}}
function cupcakeGame(){const s=session,id=s.order[s.at],w=W[id],opts=optionsFor(id,3,true),customers=['👧🏽','👩🏻','👦🏾','👵🏻','👩🏽‍🍳','🧑🏻','👧🏼','👩🏾'],frost=['🍓','🍦','🍫','🍒','🍬','🫐','🍯','🍉'],base=['🧁','🧁','🧁'];frame('🧁 Cupcake Café',`<div class="creative-progress"><span class="pill">Customer ${s.at+1} / ${s.order.length}</span><span class="pill">⭐ ${s.score} stars</span></div><div class="creative-banner"><span class="customer">${customers[s.at%customers.length]}</span><div class="order-ticket"><strong>🍰 NEW ORDER!</strong><p>“Please make me a cupcake for <strong>${esc(w[1])}</strong>!”</p><p class="subtle">Find the Hebrew shoresh on the correct topping.</p></div></div><div class="cupcake-stage"><div class="cupcake-art"><span class="topper">${s.locked?'🌟':'❔'}</span><span class="frost">${frost[s.at%frost.length]}</span><span class="base">🧁</span></div><div style="font-size:36px">${s.locked?'🎁✨':'🍽️'}</div></div><h3>Choose the Hebrew topping!</h3><div class="cupcake-picks">${opts.map((i,k)=>`<button data-cupcake="${i}" ${s.locked?'disabled':''}><span class="pick-emoji">${['🍒','🍭','🍓'][k]}</span><span class="pick-he">${W[i][0]}</span></button>`).join('')}</div><div id="creativeFeedback"></div>`,100*s.at/s.order.length);document.querySelectorAll('[data-cupcake]').forEach(b=>b.onclick=()=>creativeAnswer(Number(b.dataset.cupcake)===id,b,`🧁 ORDER SERVED! ${esc(w[0])} means ${esc(w[1])}. Your customer loves it! 💕`))}
function dressGame(){const s=session,id=s.order[s.at],w=W[id],opts=optionsFor(id,3,true),looks=[['👗','👠','🎀'],['🥻','👟','👑'],['👘','🥿','👜'],['👚','👢','🌸'],['👗','👡','💎'],['🥻','👠','🦋'],['👘','🥿','🕶️'],['👚','👟','🎀']],look=looks[s.at%looks.length],step=s.stage,labels=['dress','shoes','accessory'],pieces=step===0?['👗','👘','🥻']:step===1?['👠','👟','🥿']:['🎀','👑','👜'];frame('👗 Dream Dress-Up Studio',`<div class="creative-progress"><span class="pill">Look ${s.at+1}/${s.order.length}</span><span class="pill">Step ${step+1}/3</span><span class="pill">⭐ ${s.score}</span></div><div class="dress-stage"><div class="doll">👩🏻‍🦰</div><div class="doll-outfit"><div class="outfit-piece">${s.parts[0]||'❔'}</div><div class="outfit-piece">${s.parts[1]||'👣'}</div><div class="outfit-piece">${s.parts[2]||'✨'}</div></div></div><div class="order-ticket"><strong>✨ Style challenge!</strong><p>Choose the ${labels[step]} labeled with the Hebrew root for <strong>${esc(w[1])}</strong>.</p><p class="subtle">Don't match by color—read the Hebrew!</p></div><div class="wardrobe-grid">${opts.map((i,k)=>`<button data-outfit="${i}" ${s.locked?'disabled':''}><span class="piece">${pieces[k]}</span><span class="root">${W[i][0]}</span></button>`).join('')}</div><div id="creativeFeedback"></div>`,100*(s.at+step/3)/s.order.length);document.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>{if(s.locked)return;if(Number(b.dataset.outfit)!==id){s.tries++;audio('bad');b.disabled=true;b.classList.add('wrong');$('#creativeFeedback').innerHTML='<div class="feedback try">Try another label! The colors are just for fun. 💜</div>';return}audio('good');s.parts.push(pieces[[...b.parentNode.children].indexOf(b)]);s.stage++;if(s.stage<3){s.score+=2;award(3);s.tries=0;dressGame()}else{s.locked=true;s.score+=5;award(9);celebrate();$('#creativeFeedback').innerHTML=`<div class="feedback good">✨ Runway ready! ${esc(w[0])} = ${esc(w[1])}!</div><button class="primary" id="creativeNext">${s.at===s.order.length-1?'Finish fashion show':'Style the next look →'}</button>`;$('#creativeNext').onclick=creativeAdvance}})}
function petGame(){const s=session,id=s.order[s.at],w=W[id],opts=optionsFor(id,3,true),pets=['🐱','🐶','🐰','🐼','🦊','🐻','🐨','🐹'],tools=['🧼','🪮','🎀','🧸','🛁','🦴'];frame('🐾 Rainbow Pet Spa',`<div class="creative-progress"><span class="pill">Pet ${s.at+1}/${s.order.length}</span><span class="pill">⭐ ${s.score}</span></div><div class="pet-stage"><div class="pet-face">${pets[s.at%pets.length]}</div><div class="bigscene">${s.locked?'💖 ✨ 🌸':'🫧 🪮 🎀'}</div><h2>${s.locked?'Your pet looks fabulous!':'Welcome to the Pet Spa!'}</h2></div><div class="order-ticket"><p>Our pet wants the special treatment for <strong>${esc(w[1])}</strong>.</p><p>Tap the spa tool with the matching Hebrew shoresh!</p></div><div class="pet-tools">${opts.map((i,k)=>`<button data-pet="${i}" ${s.locked?'disabled':''}><span class="tool-emoji">${tools[(s.at+k)%tools.length]}</span><span class="tool-word">${W[i][0]}</span></button>`).join('')}</div><div id="creativeFeedback"></div>`,100*s.at/s.order.length);document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>creativeAnswer(Number(b.dataset.pet)===id,b,`🐾 Spa success! ${esc(w[0])} = ${esc(w[1])}. Your pet is delighted! ✨`))}

