const extraGames={cake:['🎂','Birthday Cake Designer','Build a cake layer by layer for a customer'],boutique:['👛','Fashion Boutique','Fill your boutique and style customer orders'],claw:['🕹️','Claw Machine','Win surprise dollhouse collectibles'],aquarium:['🐠','Aquarium Rescue','Rescue fish and decorate their aquarium'],quest:['🗺️','Adventure Missions','Short missions and mastery review']};
const extraMenu=menu;
