CALM_TOOLS.push(...[["🌿","Brain Dump","Write down what is on your mind."],["🌿","Short Walk","Take a short walk somewhere safe."],["🌿","Quiet Playlist","Listen to music that helps you settle."],["🌿","Cool Water","Sip water and notice the sensation."],["🌿","Hand Stretch","Gently stretch and relax your fingers."],["🌿","Read a Page","Read something enjoyable for a minute."],["🌿","Look Outside","Notice three things outside."],["🌿","Name the Thought","Say 'I'm having the thought that...'"],["🌿","Make a Tiny Plan","Pick one small next step."],["🌿","Talk It Out","Ask a trusted person to listen."],["🌿","Doodle Break","Draw shapes for two minutes."],["🌿","Small Puzzle","Try a short puzzle if it helps."],["🌿","Get Comfortable","Adjust your seat or clothing."],["🌿","Snack Check","Notice whether you need food."],["🌿","Rest Check","Check whether you need rest."],["🌿","Muscle Release","Tense and relax your shoulders gently."],["🌿","Fresh Air","Get some fresh air if possible."],["🌿","Kind Self-Talk","Talk to yourself like a friend."],["🌿","Control Circle","Name what you can and cannot control."],["🌿","Two-Minute Reset","Wait two minutes before your next step."]]);
let selMode='',selAt=0,selAnswered=null,selWins=0,selCalmTool='',selOrder=[];
function selHeader(title){return `<div class="gamehead"><button class="secondary" id="selBack">← Social Skills games</button><strong>${title}</strong><span class="pill">🌟 ${selWins}</span></div>`}
function selHub(){game='sel';session=null;selMode='';app.innerHTML=`<section class="sel-hero"><div style="font-size:50px">🌈🦋💖</div><h1>Social Skills & Feelings World</h1><p>Practice big feelings, friendships, flexibility, and solving tricky moments. There is no timer and you can always try again.</p><button class="secondary" id="selToHebrew">🎮 Back to Hebrew Arcade</button></section><section class="panel"><h2>✨ Choose a social skills adventure</h2><div class="sel-grid">${SEL_MODES.map(m=>`<button class="sel-card" data-sel-mode="${m.id}"><span class="sel-emoji">${m.emoji}</span><strong>${m.name}</strong><p>${m.subtitle}</p><span class="tag">${m.theme}</span></button>`).join('')}</div></section><section class="panel"><h3>💜 A note for grown-ups</h3><p>These are practice scenarios, not tests of obedience. Validate feelings, invite Riki to explain her reasoning, and discuss what might work in real life. More than one response can sometimes be reasonable. Try a skill together outside the game.</p></section>`;$('#selToHebrew').onclick=menu;document.querySelectorAll('[data-sel-mode]').forEach(b=>b.onclick=()=>{selMode=b.dataset.selMode;selAt=0;selWins=0;selAnswered=null;selOrder=Array.from({length:SEL_SCENES[selMode].length},(_,i)=>i).sort(()=>Math.random()-.5);audio('tap');selRender()})}
function selRender(){if(selMode==='reset')return selCalm();const m=SEL_MODES.find(x=>x.id===selMode),list=SEL_SCENES[selMode];if(selAt>=list.length){app.innerHTML=`<section class="panel">${selHeader('Mission complete')}<div class="sel-scene"><div class="sel-illustration">🎉💖🏆</div><h2>You practiced ${m.theme}!</h2><p>Real-life skills grow with practice. Which idea would you like to try today?</p><p>🌟 ${selWins} thoughtful choices</p><button class="primary" id="selReplay">Play again</button></div></section>`;$('#selBack').onclick=selHub;$('#selReplay').onclick=()=>{selAt=0;selWins=0;selAnswered=null;selOrder=Array.from({length:list.length},(_,i)=>i).sort(()=>Math.random()-.5);selRender()};return}
const q=list[selOrder[selAt]??selAt],done=selAnswered!==null;app.innerHTML=`<section class="panel">${selHeader(m.emoji+' '+m.name)}<p class="sel-progress">Scene ${selAt+1} of ${list.length} · No countdown</p><div class="progress"><div style="width:${100*selAt/list.length}%"></div></div><div class="sel-scene"><div class="sel-illustration">${q[0]}</div><h2>${q[1]}</h2><p>${q[2]}</p></div><div class="sel-options">${q[3].map((t,i)=>`<button class="sel-choice" data-sel-choice="${i}" ${done?'disabled':''}>${['🌷','⭐','💜'][i]} ${t}</button>`).join('')}</div>${done?`<div class="sel-feedback"><h3>${selAnswered===q[4]?'🌟 That is a helpful option!':'💜 Let’s think about another option.'}</h3><p>${q[5]}</p><p><strong>Try saying:</strong> ${q[6]}</p><button class="primary" id="selNext">${selAt===list.length-1?'Finish mission':'Next scene →'}</button></div>`:''}</section>`;$('#selBack').onclick=selHub;document.querySelectorAll('[data-sel-choice]').forEach(b=>b.onclick=()=>{selAnswered=Number(b.dataset.selChoice);if(selAnswered===q[4]){selWins++;audio('good')}else audio('tap');selRender()});if(done)$('#selNext').onclick=()=>{selAt++;selAnswered=null;selRender()}}
const CALM_TOOLS=[['🫧','Bubble Breaths','Breathe in gently, then breathe out slowly as if blowing a big bubble.'],['🖐️','Five Senses','Name five things you see, four you feel, three you hear, two you smell, and one you taste (or imagine).'],['🐢','Turtle Pause','Put your feet on the ground, relax your shoulders, and choose one small next step.'],['🎨','Color Check-In','Pick a color that matches how you feel. Draw or imagine it. There is no wrong color.'],['💬','Ask for Space','Practice saying: “I need a few minutes. I will come back.”']];
function selCalm(){app.innerHTML=`<section class="panel">${selHeader('🌈 Calm-Down Lab')}<div class="sel-scene"><div class="sel-breath">🫧</div><h2>You get to choose what helps you.</h2><p>Calming down is a skill, not a punishment. Different tools work for different people.</p></div><div class="sel-grid">${CALM_TOOLS.map((t,i)=>`<button class="sel-card" data-calm="${i}"><span class="sel-emoji">${t[0]}</span><strong>${t[1]}</strong><p>${t[2]}</p></button>`).join('')}</div>${selCalmTool?`<div class="sel-feedback"><h3>${selCalmTool}</h3><p>Try it at your own pace. Would this tool help in a real-life moment? You get to decide.</p></div>`:''}</section>`;$('#selBack').onclick=selHub;document.querySelectorAll('[data-calm]').forEach(b=>b.onclick=()=>{selCalmTool=CALM_TOOLS[Number(b.dataset.calm)][1];audio('tap');selCalm()})}
// Add a separate category entry without changing the existing Hebrew-game menu.
const hebrewMenuBeforeSEL=menu;
menu=function(){hebrewMenuBeforeSEL()};
const headerStats=document.querySelector('.stats');if(headerStats){const btn=document.createElement('button');btn.className='smallbtn';btn.textContent='💖 Social Skills';btn.onclick=selHub;headerStats.insertBefore(btn,headerStats.firstChild)}
